<span class="line"><span style="color:#E5C07B;">        Console</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">WriteLine</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;1. 生成密钥对 → 私钥留在 TPM 内部&quot;</span><span style="color:#ABB2BF;">);</span></span>
